import{_ as i,C as e,o as s,c as l,E as a,a7 as c}from"./chunks/framework.FWlv_suP.js";const b=JSON.parse('{"title":"Lingua Log Privacy Policy","description":"Privacy Policy for Lingua Log, presented within Policy Hub.","frontmatter":{"title":"Lingua Log Privacy Policy","description":"Privacy Policy for Lingua Log, presented within Policy Hub."},"headers":[],"relativePath":"apps/lingua-log/privacy.md","filePath":"apps/lingua-log/privacy.md"}'),d={name:"apps/lingua-log/privacy.md"};function p(h,o,g,u,m,y){const n=e("AppBreadcrumbs"),t=e("AppSubnav"),r=e("CopyStandaloneUrl");return s(),l("div",null,[a(n,{"app-id":"lingua-log",current:"Privacy Policy"}),a(t,{"app-id":"lingua-log"}),a(r,{path:"/privacy/lingua-log",label:"Copy Play Store URL","copied-label":"Play Store URL copied","document-name":"Lingua Log privacy policy"}),o[0]||(o[0]=c('<h1 id="privacy-policy-for-lingua-log" tabindex="-1">Privacy Policy for Lingua Log <a class="header-anchor" href="#privacy-policy-for-lingua-log" aria-label="Permalink to &quot;Privacy Policy for Lingua Log&quot;">​</a></h1><p><strong>Effective Date:</strong> August 1, 2026<br><strong>Last Updated:</strong> August 1, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Lingua Log is a multilingual learning-record application developed by <strong>Anand Raja</strong>. It helps you organize sentences, transliterations, manually supplied translations, explanations, tables, and source references using a configured Google Sheet and device-local preferences.</p><p>Lingua Log has no advertising, developer-operated analytics, or general-purpose online user account. It does not automatically translate text.</p><h2 id="language-content" tabindex="-1">Language Content <a class="header-anchor" href="#language-content" aria-label="Permalink to &quot;Language Content&quot;">​</a></h2><p>Entries can include a generated identifier, creation and update times, source language and text, transliteration, translations, formatted explanations, table contents, resource labels and links, and a protected-status flag. Supported choices include Tamil, English, Sanskrit, Hindi, Kannada, Malayalam, Telugu, French, and a user-named language.</p><p>Do not enter confidential, copyrighted, personal, or third-party information unless you are authorized to store and share it.</p><h2 id="google-sheets" tabindex="-1">Google Sheets <a class="header-anchor" href="#google-sheets" aria-label="Permalink to &quot;Google Sheets&quot;">​</a></h2><p>Lingua Log reads entries from a configured Google Sheet through Google&#39;s Visualization endpoint. The editor copies a header or tab-separated row to the system clipboard so you can paste it into Google Sheets manually; the app does not directly write or delete Sheet rows.</p><p>The Sheet owner can access all stored entry content. Google receives the spreadsheet and tab identifiers plus standard connection information such as IP address, user agent, request time, and requested resource. Google&#39;s processing is governed by the <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google Privacy Policy</a>.</p><p>A row marked <strong>Protected</strong> is hidden in the Lingua Log interface until local login. The row remains present in the Sheet response and is not encrypted by this flag. Sheet sharing permissions remain the actual access control.</p><h2 id="information-stored-on-your-device" tabindex="-1">Information Stored on Your Device <a class="header-anchor" href="#information-stored-on-your-device" aria-label="Permalink to &quot;Information Stored on Your Device&quot;">​</a></h2><p>On Android, Lingua Log caches up to 30 recently fetched Sheet entries in localStorage for offline use. The cache can include protected rows and all their entry fields. It is not encrypted.</p><p>The app also stores theme preference, a local login session containing the entered user name and a SHA-1 password hash, and optional PIN or biometric settings. Even an unsuccessful login attempt can replace the locally stored user name and password hash. Login is checked locally and is not an online identity service.</p><p>An optional 4-to-8-digit PIN is represented by a salted PBKDF2-SHA-256 verifier. On supported Android devices, optional biometric unlock uses Android BiometricPrompt and Android Keystore. Lingua Log does not receive or store biometric templates. These controls restrict the app interface; they do not encrypt the Sheet cache.</p><h2 id="clipboard-and-external-resources" tabindex="-1">Clipboard and External Resources <a class="header-anchor" href="#clipboard-and-external-resources" aria-label="Permalink to &quot;Clipboard and External Resources&quot;">​</a></h2><p>Copied TSV content may be available to Android, keyboard software, clipboard history, and other apps permitted to read the clipboard. Entries may contain links or references. Opening a link shares normal request information with the destination and is governed by its policies.</p><h2 id="information-received-by-the-developer" tabindex="-1">Information Received by the Developer <a class="header-anchor" href="#information-received-by-the-developer" aria-label="Permalink to &quot;Information Received by the Developer&quot;">​</a></h2><p>The developer does not automatically receive local login details, PIN data, cached entries, editor content, or clipboard rows. The owner of the configured Google Sheet can access Sheet content. If you contact support, the developer receives the information you choose to send.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Lingua Log uses internet access for Google Sheets, biometric permission when you enable fingerprint unlock, and clipboard access after copy or paste actions. The reviewed app does not request location, contacts, phone, SMS, call-log, camera, microphone, or notification permission.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and Deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and Deletion&quot;">​</a></h2><p>The Android cache and settings remain until refreshed, replaced, cleared through system app-storage settings, or removed when the app is uninstalled. In a browser, clear the site&#39;s storage and cache. Logging out removes only the local login session.</p><p>Clearing Lingua Log does not delete Google Sheet rows, clipboard history, or content copied elsewhere. Delete Sheet records through the relevant Google account or Sheet owner and clear external copies separately.</p><h2 id="changes-and-contact" tabindex="-1">Changes and Contact <a class="header-anchor" href="#changes-and-contact" aria-label="Permalink to &quot;Changes and Contact&quot;">​</a></h2><p>This policy may be updated when Lingua Log features or data practices change.</p><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',28))])}const v=i(d,[["render",p]]);export{b as __pageData,v as default};
